--
-- Table structure for table `fixed_asset_report_depreciation_plan_details`
--

DROP TABLE IF EXISTS `fixed_asset_report_depreciation_plan_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fixed_asset_report_depreciation_plan_details` (
  `id` varchar(64) NOT NULL COMMENT '主键',
  `plan_name` varchar(255) DEFAULT NULL,
  `asset_id` varchar(255) DEFAULT NULL COMMENT '→fixed-assets',
  `asset_name` varchar(255) DEFAULT NULL,
  `asset_type` varchar(64) DEFAULT NULL COMMENT 'ASSET_CATEGORY',
  `company_id` varchar(255) DEFAULT NULL COMMENT '→org-companies',
  `original` decimal(20,6) DEFAULT NULL,
  `residual_rate` decimal(20,6) DEFAULT NULL,
  `total_life` decimal(20,6) DEFAULT NULL,
  `used_life` decimal(20,6) DEFAULT NULL,
  `dep_date` datetime(3) DEFAULT NULL,
  `finished` tinyint(1) DEFAULT NULL,
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `version` int DEFAULT '1' COMMENT '乐观锁版本',
