--
-- Table structure for table `org_companies`
--

DROP TABLE IF EXISTS `org_companies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `org_companies` (
  `id` varchar(64) NOT NULL COMMENT '主键',
  `code` varchar(255) DEFAULT NULL COMMENT '必填 唯一',
  `name` varchar(255) DEFAULT NULL COMMENT '必填 唯一',
  `short_name` varchar(255) DEFAULT NULL,
  `parent_id` varchar(255) DEFAULT NULL COMMENT '→org-companies',
  `type` varchar(255) DEFAULT NULL,
  `credit_code` varchar(255) DEFAULT NULL,
  `legal_person` varchar(255) DEFAULT NULL,
  `contact` varchar(255) DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `status` varchar(64) DEFAULT NULL COMMENT 'ENABLE_STATUS 必填',
  `sort` bigint DEFAULT NULL,
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `version` int DEFAULT '1' COMMENT '乐观锁版本',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='公司';
/*!40101 SET character_set_client = @saved_cs_client */;

