DROP TABLE IF EXISTS `system_dict_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_dict_items` (
  `id` varchar(64) NOT NULL COMMENT '主键',
  `label` varchar(255) DEFAULT NULL COMMENT '必填',
  `value` varchar(255) DEFAULT NULL COMMENT '必填',
  `sort` bigint DEFAULT NULL,
  `status` varchar(64) DEFAULT NULL COMMENT 'ENABLE_STATUS 必填',
  `remark` varchar(255) DEFAULT NULL,
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `version` int DEFAULT '1' COMMENT '乐观锁版本',
  `dict_code` varchar(64) NOT NULL COMMENT '所属字典类型',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='字典项';
/*!40101 SET character_set_client = @saved_cs_client */;

